async function openScreenPicker(purpose="tools"){if(!window.remiDesktop){setMessage("program-learning-message","Run Remind-er 4.0 as the desktop app to choose a browser or app window.",true);return}if(recorder&&recorder.state!=="inactive"){setMessage("program-learning-message","Stop the current recording before changing its target.",true);return}if(learn?.running){setMessage("program-learning-message","Pause Self-Learning before changing its target.",true);return}screenPickerPurpose=purpose;const heading=({en:{record:"Choose a browser, program, app, or display to record",learning:"Choose a browser window to learn from",tools:"Choose a window or display"},fr:{record:"Choisir un navigateur, programme, application ou écran à enregistrer",learning:"Choisir une fenêtre de navigateur à explorer",tools:"Choisir une fenêtre ou un écran"},es:{record:"Elige un navegador, programa, aplicación o pantalla para grabar",learning:"Elige una ventana del navegador para explorar",tools:"Elige una ventana o pantalla"},de:{record:"Browser, Programm, App oder Bildschirm zur Aufnahme auswählen",learning:"Browserfenster zum Erkunden auswählen",tools:"Fenster oder Bildschirm auswählen"},pt:{record:"Escolha navegador, programa, aplicativo ou tela para gravar",learning:"Escolha uma janela do navegador para explorar",tools:"Escolha uma janela ou tela"}})[uiLanguage]?.[purpose]||"Choose a window or display";$("screen-picker-title").textContent=heading;setBarExpanded(true);const container=$("screen-sources");container.replaceChildren();$("screen-picker").hidden=false;try{const sources=await window.remiDesktop.pickScreen();if(!sources.length){const empty=document.createElement("p");empty.className="muted";empty.textContent="No windows or displays are available.";container.append(empty);return}for(const source of sources){const button=document.createElement("button");button.type="button";button.className="screen-source";const image=document.createElement("img");image.src=source.thumbnail;image.alt="";const title=document.createElement("span");title.textContent=source.name;button.append(image,title);button.addEventListener("click",async()=>{try{if(!await window.remiDesktop.chooseScreen(source.id))throw new Error("That window is no longer available.");if(window.remiScreenStream)for(const track of window.remiScreenStream.getTracks())track.stop();window.remiSelectedScreen={id:source.id,name:source.name};window.remiScreenStream=null;if(purpose==="learning")$("program-kind").value=isBrowserWindowName(source.name)?"website":"program";refreshSelectedTargetLabels();renderSuggestions();$("page-title").textContent="Selected · "+source.name;$("connection-state").textContent="Window selected";$("screen-picker").hidden=true;const message=purpose==="record"?"Selected "+source.name+". Check recording consent, then start recording.":purpose==="learning"?"Selected "+source.name+". Choose observe-only or autonomous browser learning below.":"Selected "+source.name+" for visual guidance.";setMessage("program-learning-message",message)}catch(error){setMessage("program-learning-message",error.message||"Could not select that window.",true)}});container.append(button)}}catch(error){$("screen-picker").hidden=true;setMessage("program-learning-message",error.message||"Could not list windows and displays.",true)}}
