function askDesktopAction(action){if(!window.remiDesktop||!window.remiSelectedScreen){setMessage("live-instruction","Choose a desktop window before approving an action.",true);return}pendingDesktopAction={...action,needsSecondApproval:/\b(delete|remove|purchase|buy|checkout|pay|payment|transfer|send|submit|publish|share|logout|sign out|security|password|credential|account|subscription|cancel|confirm)\b/i.test(action.instruction||"")};const summary=$("approval-action-summary");summary.textContent=action.type==="click"?"Click at "+Math.round(action.x*100)+"%, "+Math.round(action.y*100)+"% of the selected app window.":action.type==="type"?"Type the exact text shown below into the selected app.":"Press "+action.key;$("desktop-action-value").value=action.type==="type"?action.value||"":"";$("desktop-action-key").value=action.type==="key"?action.key||"":"";$("approval-dialog").querySelector("h2").textContent=pendingDesktopAction.needsSecondApproval?"Review potentially sensitive action":"Approve desktop action?";$("approval-dialog").querySelector(".muted").textContent=pendingDesktopAction.needsSecondApproval?"Remi flagged this suggestion as potentially sensitive. Confirm it a second time only if you intend to continue.":"Remi requests one action in the selected app. It only runs after you approve.";$("approve-desktop-action").textContent=pendingDesktopAction.needsSecondApproval?"Review action":"Approve once";$("approval-dialog").hidden=false}function closeActionApproval(){pendingDesktopAction=null;$("approval-dialog").hidden=true}
$("approve-desktop-action")?.addEventListener("click",async()=>{if(!pendingDesktopAction)return;if(pendingDesktopAction.needsSecondApproval&&!pendingDesktopAction.secondApproved){pendingDesktopAction.secondApproved=true;$("approval-dialog").querySelector("h2").textContent="Confirm sensitive action";$("approval-dialog").querySelector(".muted").textContent="This may change or share account data. Confirm again only if you expect this result.";$("approve-desktop-action").textContent="Confirm and run once";return}const action={...pendingDesktopAction,approvedAt:new Date().toISOString(),target:window.remiSelectedScreen?.name||"selected screen"};if(action.type==="manual"){const value=$("desktop-action-value").value,key=$("desktop-action-key").value;if(value)action.type="type",action.value=value;else if(key)action.type="key",action.key=key;else{closeActionApproval();return}}closeActionApproval();const result=await window.remiDesktop.actuate(action);if(!result.ok){setMessage("live-instruction",result.reason||"Action failed",true);return}approvedActionLog.push({...action,value:action.type==="type"?"[redacted]":action.value});approvedActionLog=approvedActionLog.slice(-30);const list=$("action-audit-list");list.replaceChildren(...approvedActionLog.slice().reverse().map(x=>{const li=document.createElement("li");li.textContent=new Date(x.approvedAt).toLocaleTimeString()+" · "+x.target+" · "+(x.type==="click"?"Click "+Math.round(x.x*100)+"%, "+Math.round(x.y*100)+"%":x.type==="type"?"Typed [redacted]":"Pressed "+x.key);return li}));setMessage("live-instruction","Approved action sent to "+result.target+". Review the app, then choose Get next suggestion.")});$("cancel-desktop-action")?.addEventListener("click",closeActionApproval);
