const STORAGE_KEY="reminder4Storage";
function updateDesktopBar(){if(!window.remiDesktop?.resize)return;const collapsed=document.body.classList.contains("collapsed"),header=$("app-header")||document.querySelector("body.bar-standalone header"),content=$("bar-content"),embed=$("bar-embed"),headerHeight=header?.getBoundingClientRect().height||72,contentHeight=collapsed?0:Math.min(428,content?.scrollHeight||0),embedHeight=embed&&!embed.hidden?embed.scrollHeight:0;window.remiDesktop.resize(Math.ceil(headerHeight+contentHeight+embedHeight))}let pendingDesktopAction=null, approvedActionLog=[];
function showTab(name,expand=true){if(name==="chat")name="tutor";if(!document.getElementById("tab-"+name))name="tutor";for(const b of document.querySelectorAll(".tab")){const active=b.id==="tab-"+name;b.classList.toggle("active",active);b.setAttribute("aria-selected",String(active))}for(const panel of document.querySelectorAll(".view")){const active=panel.id==="view-"+name;panel.hidden=!active;panel.classList.toggle("active",active)}chrome.storage.local.set({activeRemiTab:name});if(name==="settings")renderKnowledge();if(expand)setBarExpanded(true);else updateDesktopBar()}
document.querySelectorAll(".tab").forEach(button=>button.addEventListener("click",()=>showTab(button.id.replace("tab-",""),true)));window.addEventListener("resize",updateDesktopBar);window.addEventListener("DOMContentLoaded",updateDesktopBar);
