const uiTextSources = new WeakMap(), uiAttrSources = new WeakMap();
function languageName(){return ({fr:"French",es:"Spanish",de:"German",pt:"Portuguese"})[uiLanguage]||"English"}
function localizedPrompt(prompt){return uiLanguage==="en"?prompt:`Reply in ${languageName()}. Keep UI labels or exact control names in the original website language when useful. ${prompt}`}
function translateUi(){document.documentElement.lang=uiLanguage;const index=({fr:0,es:1,de:2,pt:3})[uiLanguage],walker=document.createTreeWalker(document.body,NodeFilter.SHOW_TEXT);let n;while((n=walker.nextNode())){if(!uiTextSources.has(n))uiTextSources.set(n,n.data);const original=uiTextSources.get(n),trimmed=original.trim(),row=UI_TRANSLATIONS[trimmed];if(row){const translated=uiLanguage==="en"?trimmed:row[index];if(translated){const left=original.match(/^\s*/)?.[0]||"",right=original.match(/\s*$/)?.[0]||"",value=left+translated+right;if(n.data!==value)n.data=value}}}for(const el of document.querySelectorAll("input,textarea,button,[aria-label],[title]")){let originals=uiAttrSources.get(el);if(!originals){originals=new Map();uiAttrSources.set(el,originals)}for(const attr of ["placeholder","aria-label","title"]){if(!el.hasAttribute(attr))continue;if(!originals.has(attr))originals.set(attr,el.getAttribute(attr));const value=originals.get(attr),row=UI_TRANSLATIONS[value],translated=row?(uiLanguage==="en"?value:row[index]):null;if(translated&&el.getAttribute(attr)!==translated)el.setAttribute(attr,translated)}}}async function updateUiLanguage(){const select=$("ui-language");if(uiLanguageMode!=="auto"){uiLanguage=["en","fr","es","de","pt"].includes(uiLanguageMode)?uiLanguageMode:"en";if(select)select.value=uiLanguage;translateUi();renderSuggestions();updateFullscreenLabel();renderKnowledge();return}try{await refreshTab()}catch{}const prefix=String(currentTab?.lang||"en").toLowerCase().split("-")[0];uiLanguage=["fr","es","de","pt"].includes(prefix)?prefix:"en";translateUi();renderSuggestions();updateFullscreenLabel();renderKnowledge();if(select)select.value="auto"}
$("ui-language")?.addEventListener("change",async event=>{const choice=event.currentTarget.value;uiLanguageMode=["auto","en","fr","es","de","pt"].includes(choice)?choice:"auto";await chrome.storage.local.set({uiLanguageMode});await updateUiLanguage()});
