function knowledgeText(key){const row=KNOWLEDGE_UI[key];const i=({fr:0,es:1,de:2,pt:3})[uiLanguage];return row?(i===undefined?key:row[i]):key}
function knowledgeLine(label,value){return value?knowledgeText(label)+": "+String(value):""}
function knowledgeGuidePayload(p){return {name:p.name,kind:p.kind||"website",version:p.version||"version not provided",verified:Boolean(p.verified),sitePurpose:p.sitePurpose||"",intendedUsers:p.intendedUsers||"",commonUses:p.commonUses||[],guide:String(p.guide||"").slice(0,5000),questions:p.questions||[],gaps:p.gaps||[],siteMap:(p.siteMap||[]).slice(0,15),tasks:(p.tasks||[]).slice(0,12).map(t=>({name:t.name||"",summary:t.summary||"",steps:(t.steps||[]).slice(0,6).map(s=>s.instruction||s.target||s.screen||"")}))}}
function renderKnowledge(){const known=$("knowledge-summary"),unknown=$("knowledge-gaps"),select=$("knowledge-program");if(!known||!unknown||!select)return;known.replaceChildren();unknown.replaceChildren();const line=(container,text,tag="p")=>{const el=document.createElement(tag);el.textContent=text;container.append(el);return el};if(!programs.length&&!learn){line(known,knowledgeText("No saved learning yet"));line(unknown,knowledgeText("No saved learning yet"));}if(programs.length){line(known,knowledgeText("Saved guides")+": "+programs.length,"p");for(const p of programs){const d=document.createElement("details");d.className="knowledge-guide";const summary=document.createElement("summary");summary.textContent=p.name+" · "+programKind(p)+" · "+(p.version||"version not provided");d.append(summary);const ul=document.createElement("ul");const facts=[knowledgeLine("Purpose",p.sitePurpose),knowledgeLine("Intended users",p.intendedUsers),knowledgeLine("Common uses",(p.commonUses||[]).join("; ")),knowledgeLine("Written guide",String(p.guide||"").replace(/[#*_`]/g,"").slice(0,1800)),knowledgeLine("Site map",(p.siteMap||[]).map(x=>typeof x==="string"?x:x.title||x.name||"").filter(Boolean).join("; ")),knowledgeLine("Questions recorded",(p.questions||[]).join("; ")),knowledgeLine("Saved tasks",(p.tasks||[]).map(t=>t.name||t.summary).filter(Boolean).join("; ")),knowledgeLine("Known gaps",(p.gaps||[]).join("; ")),knowledgeLine("Last learned",learnedDate(p)),knowledgeLine("Review status",p.verified?knowledgeText("Verified by you"):knowledgeText("AI draft; verify against the live site"))].filter(Boolean);for(const f of facts){const li=document.createElement("li");li.textContent=f;ul.append(li)}if(!facts.length){const li=document.createElement("li");li.textContent=knowledgeText("Not documented");ul.append(li)}d.append(ul);known.append(d);const missing=[];if(!p.sitePurpose)missing.push(knowledgeText("Purpose"));if(!p.intendedUsers)missing.push(knowledgeText("Intended users"));if(!(p.commonUses||[]).length)missing.push(knowledgeText("Common uses"));if(!(p.tasks||[]).length)missing.push(knowledgeText("Saved tasks"));if(!(p.siteMap||[]).length)missing.push(knowledgeText("Site map"));for(const gap of p.gaps||[])line(unknown,p.name+": "+gap,"p");if(missing.length)line(unknown,p.name+" · "+knowledgeText("Not documented")+": "+missing.join(", "),"p");if(!p.verified)line(unknown,p.name+": "+knowledgeText("This guide is an AI draft and has not been verified."),"p")}}if(learn){const d=document.createElement("details");d.className="knowledge-guide";const summary=document.createElement("summary");summary.textContent=knowledgeText("Current learning session")+": "+(learn.program?.name||"selected site");d.append(summary);line(d,knowledgeText("Current session not saved yet"),"p");if(learn.observations?.length){line(d,knowledgeText("Pending observations"),"b");const ul=document.createElement("ul");for(const note of learn.observations.slice(0,30)){const li=document.createElement("li");li.textContent=String(note);ul.append(li)}d.append(ul)}known.append(d);for(const gap of learn.gaps||[])line(unknown,(learn.program?.name||"")+": "+gap,"p");if(!learn.batchSavedAt||learn.frames?.length)line(unknown,knowledgeText("The current learning session has not been saved into a guide yet."),"p")}if(!unknown.childElementCount)line(unknown,knowledgeText("No explicit gaps recorded. This does not mean the guide is complete."));$("knowledge-question").placeholder=knowledgeText("Write your question in the current extension language");const previous=select.value;const opts=[new Option(knowledgeText("All saved guides"),"all"),...programs.map(p=>new Option(p.name+" · "+(p.version||"version not provided"),p.id))];if(learn)opts.push(new Option(knowledgeText("Current learning session")+": "+(learn.program?.name||"selected site"),"pending"));select.replaceChildren(...opts);if(previous&&opts.some(o=>o.value===previous))select.value=previous;else select.value="all"}
async function submitKnowledgeQuestion(){const question=$("knowledge-question").value.trim();if(!question){setMessage("knowledge-message",knowledgeText("Write a question first."),true);return}if(!$("knowledge-consent").checked){setMessage("knowledge-message",knowledgeText("Please agree before sending the question and saved guide details to your AI provider."),true);return}const selection=$("knowledge-program").value;const selected=selection==="pending"?[]:selection==="all"?programs:programs.filter(p=>p.id===selection);const active=learn&&(selection==="pending"||selection==="all"||selected.some(p=>p.name===learn.program?.name))?{program:learn.program,observations:(learn.observations||[]).slice(0,30),gaps:learn.gaps||[],status:knowledgeText("The current learning session has not been saved into a guide yet.")}:null;const context={saved_guides:selected.map(knowledgeGuidePayload),pending_session:active};const payload=JSON.stringify(context).slice(0,24000);const submit=$("knowledge-submit");submit.disabled=true;$("knowledge-consent").checked=false;$("knowledge-answer").textContent="";setMessage("knowledge-message",knowledgeText("Sending your question to the AI provider…"));try{const responseLanguage=languageName();const out=await apiCall(localizedPrompt(KNOWLEDGE_QA_PROMPT)+" Reply only in "+responseLanguage+".",{question,response_language:responseLanguage,saved_knowledge:payload},[]);const answer=String(out.answer||out.explanation||out.response||knowledgeText("No answer was returned. Please try again."));const still=Array.isArray(out.still_unknown)?out.still_unknown.filter(Boolean):out.still_unknown?[String(out.still_unknown)]:[];$("knowledge-answer").textContent=answer+(still.length?"\n\n"+knowledgeText("Known gaps")+":\n"+still.map(x=>"• "+x).join("\n"):"")+(out.follow_up?"\n\n"+out.follow_up:"");setMessage("knowledge-message",knowledgeText("Question answered in the current extension language using the selected saved knowledge."))}catch(e){setMessage("knowledge-message",friendlyError(e),true)}finally{submit.disabled=false}}
function renderPrograms(){
  programs=mergeProgramRecords(programs);
  for(const id of ["tutor-program","demo-program","live-program","program-select"])optionList($(id));
  const list=$("program-list");
  if(list)list.replaceChildren(...programs.map(p=>{
    const card=document.createElement("div");card.className="program-card";
    const title=document.createElement("b");title.textContent=p.name+" · "+programKind(p)+" · "+(p.version||"version not provided");
    const desc=document.createElement("p");desc.textContent=(p.verified?"Verified by you":"AI draft · not verified")+" · "+(p.tasks?.length||0)+" demo tasks · last learned "+learnedDate(p)+(p.preparedDemos?.length?" · "+p.preparedDemos.length+" local demo outlines ready":"");
    const details=document.createElement("details");details.className="program-guide-details";
    const summary=document.createElement("summary");summary.textContent="Open saved guide";details.append(summary);
    const purpose=String(p.sitePurpose||"").trim();if(purpose){const h=document.createElement("h3");h.textContent="Purpose";const text=document.createElement("p");text.textContent=purpose;details.append(h,text)}
    const users=String(p.intendedUsers||"").trim();if(users){const h=document.createElement("h3");h.textContent="Intended users";const text=document.createElement("p");text.textContent=users;details.append(h,text)}
    const guide=String(p.guide||"").trim();if(guide){const h=document.createElement("h3");h.textContent="Guide";const text=document.createElement("pre");text.className="program-guide-text";text.textContent=guide;details.append(h,text)}
    if(p.siteMap?.length){const h=document.createElement("h3");h.textContent="Site map";const map=document.createElement("ul");for(const item of p.siteMap.slice(0,30)){const li=document.createElement("li");li.textContent=typeof item==="string"?item:String(item.name||item.label||item.section||JSON.stringify(item));map.append(li)}details.append(h,map)}
    if(p.tasks?.length){const h=document.createElement("h3");h.textContent="Learned tasks";const tasks=document.createElement("ul");for(const task of p.tasks.slice(0,30)){const li=document.createElement("li"),name=String(task.name||task.title||task.summary||"Learned task");li.textContent=name;const steps=(task.steps||[]).slice(0,8).map((step,i)=>(i+1)+". "+String(step.instruction||step.action||step.target||step.screen||"Step")).join("\n");if(steps){const pre=document.createElement("pre");pre.className="program-guide-text";pre.textContent=steps;li.append(pre)}tasks.append(li)}details.append(h,tasks)}
    const use=document.createElement("button");use.className="secondary";use.type="button";use.textContent="Use this guide in Remi";use.addEventListener("click",()=>{for(const id of ["tutor-program","demo-program","live-program","program-select","knowledge-program"]){const select=$(id);if(select)select.value=p.id}renderSuggestions();showTab("tutor");$("tutor-question")?.focus()});
    const pdf=document.createElement("button");pdf.className="secondary";pdf.type="button";pdf.textContent=({fr:"Télécharger le guide PDF",es:"Descargar guía PDF",de:"PDF-Leitfaden herunterladen",pt:"Baixar guia em PDF"}[uiLanguage]||"Download understanding guide (PDF)");pdf.addEventListener("click",()=>downloadProgramGuide(p));
    card.append(title,desc,details,use,pdf);return card
  }));
  renderKnowledge();renderSuggestions()
}
