function compactSuggestion(value){const text=typeof value==="string"?value:value?.text||value?.suggestion||value?.title||value?.request||value?.label||"";return String(text).replace(/\s+/g," ").trim().slice(0,120)}
function suggestionCategory(p){const uses=Array.isArray(p?.commonUses)?p.commonUses:[],tasks=Array.isArray(p?.tasks)?p.tasks:[],map=Array.isArray(p?.siteMap)?p.siteMap:[],text=[p?.name,p?.sitePurpose,p?.intendedUsers,p?.guide,uses.join(" "),...tasks.map(t=>[t?.name,t?.summary].join(" ")),...map.map(x=>typeof x==="string"?x:x?.title||x?.name)].join(" ").toLowerCase();if(/course|lesson|student|education|school|formation|cours|élève|leçon|étudiant/.test(text))return"education";if(/shop|store|order|product|cart|commerce|commande|produit|panier|boutique/.test(text))return"shopping";if(/bank|finance|invoice|statement|transaction|payment|facture|banque|paiement|compte bancaire/.test(text))return"finance";if(/social|post|feed|community|profile|publication|communauté|fil d’actualité/.test(text))return"social";if(/project|task|workspace|calendar|board|document|projet|tâche|espace de travail|calendrier/.test(text))return"productivity";return"general"}
function suggestionTokens(value){const ignored=new Set("the and for from with this that how what where when into open find search page site website app program of a an to in on is are use using view show get learn help about my me it can please guide this these le la les de des du un une sur dans pour avec comment où ou et ma mon mes je aide cette ce ces page site programme application trouver chercher ouvrir expliquer moi une un est sont voir depuis como como para con una un los las por que abrir buscar explicar donde die der das und für mit meine mir eine ein auf wie finde zeigen se a o de da para com meu minha encontrar mostrar".split(" "));return [...new Set((String(value||"").toLowerCase().normalize("NFKD").replace(/[\u0300-\u036f]/g,"").match(/[a-z0-9]{3,}/g)||[]).filter(token=>!ignored.has(token)))]}
function buildSuggestionDeck(p){const key=p?.id||"general",language=BASIC_SUGGESTIONS[uiLanguage]?uiLanguage:"en",category=suggestionCategory(p),saved=(Array.isArray(p?.suggestions)?p.suggestions:[]).map(compactSuggestion).filter(Boolean),specialized=SUGGESTION_SETS[category]||SUGGESTION_SETS.general,generic=BASIC_SUGGESTIONS[language]||BASIC_SUGGESTIONS.en,uses=Array.isArray(p?.commonUses)?p.commonUses:[],tasks=Array.isArray(p?.tasks)?p.tasks:[],context=suggestionTokens([p?.name,p?.sitePurpose,p?.guide,uses.join(" "),...tasks.map(t=>[t?.name,t?.summary].join(" "))].join(" ")),items=new Map();for(const [text,source,base]of [...saved.map(x=>[x,"saved",8]),...specialized.map(x=>[x,"context",5]),...generic.map(x=>[x,"general",0])]){const clean=compactSuggestion(text);if(!clean)continue;const tokens=suggestionTokens(clean),score=base+tokens.reduce((n,t)=>n+(context.includes(t)?3:0),0);if(!items.has(clean)||items.get(clean).score<score)items.set(clean,{text:clean,score,source})}const ranked=[...items.values()].sort((a,b)=>b.score-a.score).slice(0,10);for(let i=ranked.length-1;i>0;i--){const j=Math.floor(Math.random()*(i+1));[ranked[i],ranked[j]]=[ranked[j],ranked[i]]}return ranked.map(x=>x.text)}
function reshuffleSuggestionDeck(programId){for(const key of [...suggestionDecks.keys()])if(key.startsWith(String(programId||"general")+"|"))suggestionDecks.delete(key)}
function translateSuggestion(raw){const translations=SUGGESTION_TRANSLATIONS[raw];return uiLanguage!=="en"&&translations?translations[["fr","es","de","pt"].indexOf(uiLanguage)]||raw:raw}
