async function sharedCatalogKey(demo){const raw=[demo.program||demo.program_name,demo.version||demo.program_version,demo.request||demo.title,demo.language||"en"].map(x=>String(x||"").trim().toLowerCase()).join("|");const bytes=await crypto.subtle.digest("SHA-256",new TextEncoder().encode(raw));return [...new Uint8Array(bytes)].map(x=>x.toString(16).padStart(2,"0")).join("")}
function sharedRowToDemo(row){return {id:"shared:"+row.id,catalogKey:row.catalog_key,title:row.title,notes:"",steps:Array.isArray(row.steps)?row.steps:[],program:row.program_name,programName:row.program_name,programKind:row.program_kind,programVersion:row.program_version,version:row.program_version,request:row.request,language:row.language,createdAt:row.created_at,source:"shared",frameProgramId:null,programId:null}}
async function syncSharedDemos(testOnly=false){const fields=readSharedDbFields();if(fields.url||fields.key)await chrome.storage.local.set({sharedDemoDbUrl:fields.url,sharedDemoDbKey:fields.key});const rows=await sharedDbFetch("/rest/v1/remi_shared_demos?select=id,catalog_key,program_name,program_kind,program_version,title,request,language,steps,created_at&order=created_at.desc&limit=500");if(testOnly){setMessage("shared-library-message","Connected. The shared library contains "+rows.length+" demo(s).");return rows.length}const local=demos.filter(x=>x.source!=="shared"),seen=new Set(local.map(x=>x.catalogKey).filter(Boolean)),merged=[...local];for(const row of rows){if(row.catalog_key&&seen.has(row.catalog_key))continue;const d=sharedRowToDemo(row);merged.push(d);if(row.catalog_key)seen.add(row.catalog_key)}demos=merged.slice(-500);await chrome.storage.local.set({demos});renderDemoList();renderSuggestions();setMessage("shared-library-message","Synced "+rows.length+" shared demo(s). New demos you create will be added for other connected users.");return rows.length}
async function publishSharedDemo(demo,program){const catalogKey=demo.catalogKey||await sharedCatalogKey(demo);const existing=await sharedDbFetch("/rest/v1/remi_shared_demos?select=id&catalog_key=eq."+catalogKey+"&limit=1");if(existing.length){demo.catalogKey=catalogKey;return false}const steps=(demo.steps||[]).slice(0,5).map(x=>({frame:Number.isInteger(x.frame)?x.frame:null,x:Number.isFinite(x.x)?x.x:null,y:Number.isFinite(x.y)?x.y:null,screen:String(x.screen||"").slice(0,220),target:String(x.target||"").slice(0,180),instruction:String(x.instruction||"").slice(0,300)}));const row={catalog_key:catalogKey,program_name:String(program.name).slice(0,160),program_kind:program.kind==="program"?"program":"website",program_version:String(program.version||"version not provided").slice(0,80),title:String(demo.title||demo.request||"Simple navigation demo").slice(0,160),request:String(demo.request||"").slice(0,240),language:["en","fr","es","de","pt"].includes(demo.language)?demo.language:"en",steps};try{await sharedDbFetch("/rest/v1/remi_shared_demos",{method:"POST",headers:{Prefer:"return=minimal"},body:JSON.stringify(row)})}catch(e){if(e.status!==409)throw e}demo.catalogKey=catalogKey;return true}
async function publishSharedGuideWorkflows(program){const db=await chrome.storage.local.get(["sharedDemoDbUrl","sharedDemoDbKey"]);if(!db.sharedDemoDbUrl||!db.sharedDemoDbKey)return 0;let saved=0;for(const task of (program.tasks||[]).filter(x=>Array.isArray(x.steps)&&x.steps.length).slice(0,10)){const name=String(task.name||task.title||task.summary||"").trim();if(!name)continue;const steps=task.steps.slice(0,5).map(s=>({frame:Number.isInteger(s.frame)?s.frame:null,x:Number.isFinite(s.x)?s.x:null,y:Number.isFinite(s.y)?s.y:null,screen:String(s.screen||s.expected||"").slice(0,220),target:String(s.target||"").slice(0,180),instruction:String(s.instruction||s.action||s.description||"").slice(0,300)}));if(!steps.some(s=>s.instruction||s.target))continue;try{if(await publishSharedDemo({title:"Guide: "+name,request:name,program:program.name,version:program.version||"version not provided",language:uiLanguage,steps},program))saved++}catch(error){console.warn("Remi could not share a saved guide workflow:",error?.message||error);break}}return saved}
async function refreshApiConnectionCard(){const provider=$("api-provider").value, keyName=provider==="nvidia"?"nvidiaApiKey":"apiKey", saved=await chrome.storage.local.get([keyName,"lastAIConnectionTest"]), key=String(saved[keyName]||"").trim(), entered=String($("api-key").value||"").trim(), status=$("api-key-status"), card=$("api-test-result"), result=$("api-test-result-text");status.textContent=(key?"Saved key for "+(provider==="nvidia"?"NVIDIA":"OpenAI")+": Yes (hidden)":"Saved key for "+(provider==="nvidia"?"NVIDIA":"OpenAI")+": No")+(entered&&entered!==key?" · New key entered but not saved":"");const last=saved.lastAIConnectionTest;if(last&&last.provider===provider){const when=last.checkedAt?new Date(last.checkedAt).toLocaleString():"";card.dataset.state=last.ok?"success":"error";result.textContent=(last.ok?"Connected":"Connection failed")+(when?" · "+when:"")+(last.message?" · "+last.message:"")}else{card.dataset.state="idle";result.textContent="No connection test run yet for this provider."}}async function loadProviderSettings(provider){const saved=await chrome.storage.local.get(["apiKey","apiEndpoint","apiModel","nvidiaApiKey","nvidiaApiEndpoint","nvidiaApiModel"]);if(provider==="nvidia"){$("api-key").value=saved.nvidiaApiKey||"";$("api-endpoint").value=saved.nvidiaApiEndpoint||NVIDIA_API_DEFAULT;$("api-model").value=saved.nvidiaApiModel||NVIDIA_MODEL_DEFAULT}else{$("api-key").value=saved.apiKey||"";$("api-endpoint").value=saved.apiEndpoint||API_DEFAULT;$("api-model").value=saved.apiModel||"gpt-6-luna"}$("api-endpoint").placeholder=provider==="nvidia"?NVIDIA_API_DEFAULT:API_DEFAULT;$("api-model").placeholder=provider==="nvidia"?NVIDIA_MODEL_DEFAULT:"Model ID"}
async function persistAIProviderSettings(values){const stamped={...values,aiProviderSettingsUpdatedAt:Date.now()};await chrome.storage.local.set(stamped);if(window.remiDesktop?.load&&window.remiDesktop?.save){const disk=await window.remiDesktop.load()||{};await window.remiDesktop.save({...disk,...stamped})}return stamped}
$("api-provider").addEventListener("change",()=>{const provider=$("api-provider").value;providerSettingsReady=(async()=>{const key=$("api-key"),endpoint=$("api-endpoint"),model=$("api-model");key.value="";endpoint.value="";model.value="";setMessage("settings-message","Loading "+(provider==="nvidia"?"NVIDIA":"OpenAI")+" settings…");await loadProviderSettings(provider);await refreshApiConnectionCard()})();updateTutorResearchAvailability()});
function updateTutorResearchAvailability(){const input=$("tutor-research"),note=$("tutor-context-note");if(!input||!note)return;const openai=$("api-provider").value==="openai";input.disabled=!openai;note.textContent=openai?"Remi can use the current page for context. Optional live web research sends your question to OpenAI and may add API charges.":"Remi can use the current page for context. Live web research is available only when OpenAI is selected."}
