$("forget-key").addEventListener("click",async()=>{$("api-key").value="";await chrome.storage.local.remove($("api-provider").value==="nvidia"?"nvidiaApiKey":"apiKey");setMessage("settings-message","Removed the saved API key for this provider from this browser.");await refreshApiConnectionCard()});
$("test-shared-library").addEventListener("click",async()=>{try{const fields=readSharedDbFields();if(!fields.url||!fields.key)throw new Error("Enter the Supabase project URL and publishable key first.");const url=validateSharedDbUrl(fields.url);if(!await requestApiPermission(url))throw new Error("Allow Remind-er to connect to this Supabase project.");const prior=await chrome.storage.local.get(["sharedDemoDbUrl","sharedDemoDbKey"]);await chrome.storage.local.set({sharedDemoDbUrl:url,sharedDemoDbKey:fields.key});if(prior.sharedDemoDbUrl!==url||prior.sharedDemoDbKey!==fields.key)await chrome.storage.local.remove("sharedDemoDbSession");setMessage("shared-library-message","Connecting to Supabase…");await syncSharedDemos(true);await syncSharedDemos()}catch(e){setMessage("shared-library-message",friendlyError(e),true)}});
